<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $id = get_current_user_id(); $user = get_userdata( $id ); $errors = get_transient( 'nekoko_profile_errors_' . $id ); $notice = get_transient( 'nekoko_profile_notice_' . $id ); $password_error = get_transient( 'nekoko_profile_password_error_' . $id ); delete_transient( 'nekoko_profile_errors_' . $id ); delete_transient( 'nekoko_profile_notice_' . $id ); delete_transient( 'nekoko_profile_password_error_' . $id ); ?>
<section class="nekoko-dashboard"><h2>Moj profil</h2><?php echo nekoko_core_dashboard_nav(); ?><?php if ( $notice ) { echo nekoko_core_form_notice( $notice ); } if ( $errors instanceof WP_Error ) { echo nekoko_core_form_errors( $errors ); } if ( $password_error ) { echo nekoko_core_form_notice( $password_error, 'error' ); } ?><form class="nekoko-form" method="post" action=""><?php wp_nonce_field( 'nekoko_profile_form' ); ?><input type="hidden" name="nekoko_profile_form" value="1"><p><label>Korisničko ime</label><input value="<?php echo esc_attr( $user->user_login ); ?>" disabled></p><p><label>Ime *<input name="first_name" required autocomplete="given-name" value="<?php echo esc_attr( $user->first_name ); ?>"></label></p><p><label>Prezime *<input name="last_name" required autocomplete="family-name" value="<?php echo esc_attr( $user->last_name ); ?>"></label></p><p><label>Prikazano ime *<input name="display_name" required value="<?php echo esc_attr( $user->display_name ); ?>"></label></p><p><label>Email adresa *<input type="email" name="user_email" required autocomplete="email" value="<?php echo esc_attr( $user->user_email ); ?>"></label></p><p><label>Trenutna lozinka (samo za promenu emaila)<input type="password" name="current_password" autocomplete="current-password"></label></p><p><label>Telefon<input name="nekoko_phone" value="<?php echo esc_attr( get_user_meta( $id, 'nekoko_phone', true ) ); ?>"></label></p><p><label>Grad/opština<input name="nekoko_city" value="<?php echo esc_attr( get_user_meta( $id, 'nekoko_city', true ) ); ?>"></label></p><p><label>Kratak opis<textarea name="nekoko_profile_bio" maxlength="500"><?php echo esc_textarea( get_user_meta( $id, 'nekoko_profile_bio', true ) ); ?></textarea></label></p><p><label><input type="checkbox" name="nekoko_show_phone" value="1" <?php checked( get_user_meta( $id, 'nekoko_show_phone', true ), '1' ); ?>> Dozvoljavam da moj telefon bude javno prikazan</label></p><button type="submit">Sačuvajte profil</button></form><?php if ( get_user_meta( $id, 'nekoko_pending_email', true ) ) { ?><p>Čeka potvrdu: <?php echo esc_html( get_user_meta( $id, 'nekoko_pending_email', true ) ); ?> · <a href="<?php echo esc_url( wp_nonce_url( add_query_arg( 'nekoko_cancel_email', '1', nekoko_core_page_url( 'moj-profil' ) ), 'nekoko_cancel_email' ) ); ?>">Otkažite promenu</a></p><?php } ?><form class="nekoko-form" method="post" action=""><h3>Promenite lozinku</h3><?php wp_nonce_field( 'nekoko_profile_password' ); ?><input type="hidden" name="nekoko_profile_password" value="1"><p><label>Trenutna lozinka *<input type="password" name="current_password" required autocomplete="current-password"></label></p><p><label>Nova lozinka *<input type="password" name="new_password" required minlength="10" autocomplete="new-password"></label></p><p><label>Ponovite novu lozinku *<input type="password" name="new_password_repeat" required minlength="10" autocomplete="new-password"></label></p><button type="submit">Promenite lozinku</button></form></section>
